SELECT L.ID, COALESCE(LC.TITULO, L.TITULO) TITULO, COALESCE(LC.AUTOR, L.AUTOR) AUTOR, L.TRECHO, L.SEGUNDO, V.ID VIDEO_ID, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci LEFT JOIN LIVROS_CATALOGO LC ON LC.ID = N.CATALOGO_ID JOIN VIDEOS V ON V.ID = L.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS = 'ESTUDADO' AND (N.ID IS NULL OR N.ESTADO = 'OK') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci = (SELECT COALESCE(C2.TITULO, X.TITULO) COLLATE utf8mb4_0900_ai_ci FROM LIVROS_INDICADOS X LEFT JOIN LIVROS_NOMES N2 ON N2.NOME = X.TITULO COLLATE utf8mb4_0900_ai_ci LEFT JOIN LIVROS_CATALOGO C2 ON C2.ID = N2.CATALOGO_ID WHERE X.ID = {{id}}) ORDER BY V.PUBLICADO_EM DESC, L.SEGUNDO